import{_ as a,o as i,c as o,ag as t}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"UncivCN Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Changelog.md","filePath":"UncivCN/Changelog.md"}'),l={name:"UncivCN/Changelog.md"};function n(r,e,d,s,u,c){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="uncivcn-changelog" tabindex="-1">UncivCN Changelog <a class="header-anchor" href="#uncivcn-changelog" aria-label="Permalink to &quot;UncivCN Changelog&quot;">​</a></h1><p>Version rule: upstream version + CN sub-version (<code>.1</code>, <code>.2</code>, <code>.3</code>…; the same upstream version can have multiple CN sub-versions, e.g. 4.20.8.1 → 4.20.8.4; restarts at <code>.1</code> after merging a new upstream, e.g. 4.21.5 → 4.21.5.1).</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li>Docs: the Units.json field reference now documents the <code>maxHP</code> field (default 100, adjustable via the <code>[relativeAmount] Max HP</code> unique); the city strength formula in Miscellaneous JSON files now uses the garrisoned unit&#39;s HP percentage instead of assuming a max HP of 100</li><li>CI: trimmed the workflows triggered by daily branch pushes - the Docker image publish workflow no longer runs on every push (kept the daily schedule, release tags, PR build check and manual dispatch), conflict marking no longer re-scans on branch pushes (still runs for PRs), and pure docs-only changes skip the code test workflows (Build and test / Detekt) since the docs workflow recompiles via generateDocs</li></ul><h2 id="_4-21-8-1-build-1253" tabindex="-1">4.21.8.1 (build 1253) <a class="header-anchor" href="#_4-21-8-1-build-1253" aria-label="Permalink to &quot;4.21.8.1 (build 1253)&quot;">​</a></h2><ul><li>Merged upstream 4.21.8 (17 commits): the View refactor continues (#15280) - fog-of-war view usage unified (<code>getGameViewConsideringForOfWar</code>), Empire overview tabs migrated to Views, trade UI view-ified in two steps, CityScreen migrated to <code>TileView</code>; new non-vanilla ranking type Tiles Explored (enabled by the <code>Show additional stat types</code> new-game option) and spectator slot for max players (Max players with spectator); crash-screen OOM, tech picker and notification overview ANRs, rivers on water near Rock of Gibraltar, and dev-console resource filter visibility fixed; docs reorganized (<code>Simulations</code> moved to Developers and renamed <code>Testing AI changes</code>, Regions merged into the map JSON doc, trailer audio credits merged into Credits)</li><li>Conflict resolution on merge: CN version bumped to 4.21.8.1 (build 1253); Simplified Chinese translations added for Show additional stat types and Tiles Explored; EN/ZH docs followed the upstream reorganization (standalone Other/Regions, Other/Simulations and Credits_trailer pages removed, VitePress sidebar updated); lua-api.lua / lua-map-api.lua regenerated via generateDocs (version header sync)</li><li>Difficulty: AI unhappiness modifier for King and above is now 100/90/85/75 (was 90/85/75/60), matching verified in-game values</li><li>Modding: unit max HP is now moddable - <code>maxHP</code> field in Units.json (default 100) plus the new <code>[relativeAmount] Max HP</code> unique; combat wounded penalty now scales with HP percentage, AI/UI thresholds made relative, Lua <code>unit.getMaxHealth()</code> reflects the moddable max HP</li><li>Main menu bottom-right buttons: the Discord entry is now a QQ group link (qm.qq.com), added a Baidu Tieba button, and the GitHub button points to the CN fork repository; the About page&#39;s repository/changelog/README links point to the UncivCN fork (with version anchors fixed)</li><li>Docs site links adapt to the client language: Simplified/Traditional Chinese clients jump to the Chinese section (/zh/), other languages jump to the English section</li><li>CI: detekt / Docker release workflows now trigger on the UncivCN branch (previously bound to upstream master and never ran), and release detection only accepts 4-segment version numbers; removed the upstream uncivbot auto-release bot (CN releases manually)</li><li>In-game wiki links now point to the CN docs site (club.unciv.cn), and the load-failure notice email is now <a href="mailto:hurxwork@qq.com" target="_blank" rel="noreferrer">hurxwork@qq.com</a></li><li>Code cleanup &amp; bugfixes from the full-project code review: dead code and commented-out blocks removed, <code>ConditionalBuildingBuiltAll</code> city filters and multi-segment <code>{A} {B}</code>/<code>non-[X]</code> filters fixed, <code>LongPriorityQueue.remove</code> no longer deletes the wrong element, <code>stateBasedRandom</code> no longer crashes headless map-generation tests</li><li>CI: fixed detekt analysis failures - removed deprecated config properties (<code>OptionalWhenBraces</code>; <code>ForbiddenComment</code> <code>values</code>/<code>customMessage</code> now <code>comments</code>) and added the missing end-of-file newline in <code>UnitPresenter.kt</code></li></ul><h2 id="_4-21-7-2-build-1252" tabindex="-1">4.21.7.2 (build 1252) <a class="header-anchor" href="#_4-21-7-2-build-1252" aria-label="Permalink to &quot;4.21.7.2 (build 1252)&quot;">​</a></h2><ul><li>Android: update popup downloads the APK in-game with progress and installs it via FileProvider (unknown-sources permission guided)</li><li>Android: downloads are interruption-safe (<code>.part</code> + atomic rename), Install/Redownload buttons, copy to the public Downloads folder, old packages cleaned up</li><li>Main menu &quot;Download latest version&quot; now lists the platform&#39;s installers from the release assets and downloads the chosen one directly</li></ul><h2 id="_4-21-7-1-build-1251" tabindex="-1">4.21.7.1 (build 1251) <a class="header-anchor" href="#_4-21-7-1-build-1251" aria-label="Permalink to &quot;4.21.7.1 (build 1251)&quot;">​</a></h2><ul><li>Merged upstream 4.21.7 / 4.21.7-patch1 / patch2 (41 commits): View refactor continues (#15280), AI war-logic fixes, Stealth Bomber Evasion, MP average turn times, minimap ANR fix, Gradle 9.4.1 + LibGDX 1.14.2 + target SDK 36; CN notes/pins and auto-lock adapted to the new View APIs</li><li>CI: fixed <code>unciv-lua-api</code> vsix packaging</li><li>Modder tooling: Lua API definitions auto-deployed to the docs site; <code>unciv-lua-api</code> VSCode extension syncs them into LuaLS</li><li>Docs: Lua API and map-script references generated from Kotlin data tables; toolchain no longer needs Python</li><li>Lua API: added <code>unit.getEraNumber()</code> and <code>civ.discoverTech()</code></li><li>Mods: CoeHarMod now a git submodule (standalone repo), rules consolidated via Lua</li></ul><h2 id="_4-21-6-6-build-1250" tabindex="-1">4.21.6.6 (build 1250) <a class="header-anchor" href="#_4-21-6-6-build-1250" aria-label="Permalink to &quot;4.21.6.6 (build 1250)&quot;">​</a></h2><ul><li>Automatic update check on the main menu (mirror fallback); &quot;Mod download source&quot; renamed &quot;Download source&quot;</li><li>Fixed Lua runtime crash on function-call arguments in custom API functions</li><li>Lua API expansion (~100 new methods), <code>ConditionalLuaCheck</code> unique, <code>TriggerUponTradeMade</code> hook</li><li>Lua map scripts: mods can ship a map generator (<code>scripts/</code>), new &quot;Lua Generated&quot; map type</li><li>Lua sandbox hardening; mod checker covers map-script APIs</li></ul><h2 id="_4-21-6-5-build-1249" tabindex="-1">4.21.6.5 (build 1249) <a class="header-anchor" href="#_4-21-6-5-build-1249" aria-label="Permalink to &quot;4.21.6.5 (build 1249)&quot;">​</a></h2><ul><li>Docs: Lua sections rewritten, EmmyLua type definitions + <code>LuaStarterMod</code> template, mod-ci CLI</li><li>Lua runtime errors show line numbers; sandbox escape via <code>package.loaded</code> closed; instruction budget against runaway loops</li><li>New: multiplayer restart votes (host enables, everyone votes, timeout = agree, auto-restart)</li><li>CI: Release title is the plain version number</li></ul><h2 id="_4-21-6-4-build-1248" tabindex="-1">4.21.6.4 (build 1248) <a class="header-anchor" href="#_4-21-6-4-build-1248" aria-label="Permalink to &quot;4.21.6.4 (build 1248)&quot;">​</a></h2><ul><li>CI: Release notes now contain the CN changelog in EN + ZH</li><li>New: &quot;Mod download source&quot; setting with China mirror support</li><li>New-game screen: save/load setups to named slots; clipboard buttons moved; &quot;Reset to defaults&quot; replaced by a built-in &quot;Default setup&quot;</li><li>Docs: release checklist &amp; lessons learned added to Coding-standards</li></ul><h2 id="_4-21-6-3-build-1247" tabindex="-1">4.21.6.3 (build 1247) <a class="header-anchor" href="#_4-21-6-3-build-1247" aria-label="Permalink to &quot;4.21.6.3 (build 1247)&quot;">​</a></h2><ul><li>Fixed Docker build copying stale <code>Unciv.jar</code> name; fixed MSI missing from releases</li></ul><h2 id="_4-21-6-2-build-1246" tabindex="-1">4.21.6.2 (build 1246) <a class="header-anchor" href="#_4-21-6-2-build-1246" aria-label="Permalink to &quot;4.21.6.2 (build 1246)&quot;">​</a></h2><ul><li>Fixed 47 missing + 10 empty Simplified Chinese translations for CN-specific UI strings</li></ul><h2 id="_4-21-6-1-build-1245" tabindex="-1">4.21.6.1 (build 1245) <a class="header-anchor" href="#_4-21-6-1-build-1245" aria-label="Permalink to &quot;4.21.6.1 (build 1245)&quot;">​</a></h2><ul><li>Notes keyed by gameId (no more leaking across saves)</li><li>Map/unit pins: long-press / Alt+click editing, note bubbles, crash fix, CN translations</li><li>ModOptions.json: <code>modVersion</code> / <code>gameVersionRange</code> / <code>modDependencies</code></li><li>Fixed duplicate size rows on the new-game screen; aligned bundled rulesets with upstream</li><li>Merged upstream 4.21.6 (CPU perf, AI worker adjacency, MP upload indicator)</li><li>Docs site fixes (~250 anchors), in-game version auto-synced from BuildConfig.kt</li></ul><h2 id="_4-21-5-3-build-1244" tabindex="-1">4.21.5.3 (build 1244) <a class="header-anchor" href="#_4-21-5-3-build-1244" aria-label="Permalink to &quot;4.21.5.3 (build 1244)&quot;">​</a></h2><ul><li>Fixed CI test failures (translation template spaces, test mods tracked in repo)</li><li>Deploy no longer posts to Discord</li></ul><h2 id="_4-21-5-2-build-1243" tabindex="-1">4.21.5.2 (build 1243) <a class="header-anchor" href="#_4-21-5-2-build-1243" aria-label="Permalink to &quot;4.21.5.2 (build 1243)&quot;">​</a></h2><ul><li>Official VitePress docs site (Chinese full-text search, EN/CN switch)</li><li><code>docDescriptionZh</code>: unique docs in Chinese</li><li>Local APK signing, UncivCN artifact names</li></ul><h2 id="_4-21-5-1-build-1242" tabindex="-1">4.21.5.1 (build 1242) <a class="header-anchor" href="#_4-21-5-1-build-1242" aria-label="Permalink to &quot;4.21.5.1 (build 1242)&quot;">​</a></h2><ul><li>Merged upstream 4.21.5 (AI war-logic fixes, CPU perf)</li><li>Unbundled the UCCC mod; new: export/import game setup to clipboard; citizen auto-lock tweaks; stats-display bug fixed</li></ul><h2 id="_4-21-0-2-2026-08-01" tabindex="-1">4.21.0.2 (2026-08-01) <a class="header-anchor" href="#_4-21-0-2-2026-08-01" aria-label="Permalink to &quot;4.21.0.2 (2026-08-01)&quot;">​</a></h2><ul><li>Fixed UCCC mod bugs</li></ul><h2 id="_4-21-0-1-2026-08-01" tabindex="-1">4.21.0.1 (2026-08-01) <a class="header-anchor" href="#_4-21-0-1-2026-08-01" aria-label="Permalink to &quot;4.21.0.1 (2026-08-01)&quot;">​</a></h2><ul><li>Synced recent upstream (mirror maps, stats panel); completed Chinese localization</li><li>Default MP server <code>sp.unciv.cn:30123</code>; citizen auto-lock button; bundled UCCC mod</li><li>RNG re-roll on load disabled in multiplayer</li></ul><h2 id="_4-20-17-2-2026-07-12" tabindex="-1">4.20.17.2 (2026-07-12) <a class="header-anchor" href="#_4-20-17-2-2026-07-12" aria-label="Permalink to &quot;4.20.17.2 (2026-07-12)&quot;">​</a></h2><ul><li>New: unit/map pins; radius parity restriction lifted; save version isolation; no more starvation when training settlers</li></ul><h2 id="_4-20-17-1-2026-07-04" tabindex="-1">4.20.17.1 (2026-07-04) <a class="header-anchor" href="#_4-20-17-1-2026-07-04" aria-label="Permalink to &quot;4.20.17.1 (2026-07-04)&quot;">​</a></h2><ul><li>Followed a month of upstream updates</li></ul><h2 id="_4-20-8-4-2026-05-26" tabindex="-1">4.20.8.4 (2026-05-26) <a class="header-anchor" href="#_4-20-8-4-2026-05-26" aria-label="Permalink to &quot;4.20.8.4 (2026-05-26)&quot;">​</a></h2><ul><li>Mod checker lints Lua errors; polling MP shows online status</li></ul><h2 id="_4-20-8-3-2026-05-23" tabindex="-1">4.20.8.3 (2026-05-23) <a class="header-anchor" href="#_4-20-8-3-2026-05-23" aria-label="Permalink to &quot;4.20.8.3 (2026-05-23)&quot;">​</a></h2><ul><li>Lua system enhanced; events hookable with Lua</li></ul><h2 id="_4-20-8-2-2026-05-22" tabindex="-1">4.20.8.2 (2026-05-22) <a class="header-anchor" href="#_4-20-8-2-2026-05-22" aria-label="Permalink to &quot;4.20.8.2 (2026-05-22)&quot;">​</a></h2><ul><li>Mods support <a href="/Unciv/Modders/Lua-Modding.html">Lua scripting</a></li><li>Fixed G&amp;K &quot;Elite Education&quot; not granting great people; TRY_INJECT cost bug</li><li>Amount parameters accept Countables</li></ul><h2 id="_4-20-8-1-2026-05-21" tabindex="-1">4.20.8.1 (2026-05-21) <a class="header-anchor" href="#_4-20-8-1-2026-05-21" aria-label="Permalink to &quot;4.20.8.1 (2026-05-21)&quot;">​</a></h2><ul><li>New: <a href="./Polling-multiplayer.html">polling multiplayer</a></li></ul><h2 id="_4-20-7-4-2026-05-19" tabindex="-1">4.20.7.4 (2026-05-19) <a class="header-anchor" href="#_4-20-7-4-2026-05-19" aria-label="Permalink to &quot;4.20.7.4 (2026-05-19)&quot;">​</a></h2><ul><li>Center-symmetric maps distribute resources symmetrically</li></ul><h2 id="_4-20-7-3-2026-05-19" tabindex="-1">4.20.7.3 (2026-05-19) <a class="header-anchor" href="#_4-20-7-3-2026-05-19" aria-label="Permalink to &quot;4.20.7.3 (2026-05-19)&quot;">​</a></h2><ul><li>Extended mod JSON system, see <a href="/Unciv/Modders/Mod-file-structure/6-MergeActions.html">MergeAction tutorial</a></li></ul><h2 id="_4-20-7-2" tabindex="-1">4.20.7.2 <a class="header-anchor" href="#_4-20-7-2" aria-label="Permalink to &quot;4.20.7.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-19</p><ul><li>Android builds no longer bundle CoeHarMod</li><li>New: three mirrored map modes (2/3/6-fold center symmetry)</li></ul><h2 id="_4-20-6-3" tabindex="-1">4.20.6.3 <a class="header-anchor" href="#_4-20-6-3" aria-label="Permalink to &quot;4.20.6.3&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-17</p><ul><li>New mod uniques:</li></ul><table tabindex="0"><thead><tr><th>English text</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>No longer shown in the city panel</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>Can be built [amount] times in a single city</td></tr></tbody></table><h2 id="_4-20-6-1" tabindex="-1">4.20.6.1 <a class="header-anchor" href="#_4-20-6-1" aria-label="Permalink to &quot;4.20.6.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-05-16</p><ul><li>Synced two months of upstream updates</li><li>Random-result variability folded into a settings toggle</li></ul><h2 id="_4-19-16-2" tabindex="-1">4.19.16.2 <a class="header-anchor" href="#_4-19-16-2" aria-label="Permalink to &quot;4.19.16.2&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-02</p><ul><li>Ancient-ruin results re-rollable by reloading a save</li></ul><h2 id="_4-19-16-1" tabindex="-1">4.19.16.1 <a class="header-anchor" href="#_4-19-16-1" aria-label="Permalink to &quot;4.19.16.1&quot;">​</a></h2><p><strong>Released</strong>: 2026-03-01</p><ul><li>City-state quest results re-rollable by reloading a save</li></ul><h2 id="_4-19-15-cn2" tabindex="-1">4.19.15-cn2 <a class="header-anchor" href="#_4-19-15-cn2" aria-label="Permalink to &quot;4.19.15-cn2&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-28</p><ul><li>New area-attack mod uniques (multi-target, distance falloff, self/counter damage)</li><li>Stats panel CSV export</li></ul><h2 id="_4-19-15" tabindex="-1">4.19.15 <a class="header-anchor" href="#_4-19-15" aria-label="Permalink to &quot;4.19.15&quot;">​</a></h2><p><strong>Released</strong>: 2026-02-26</p><ul><li>Android bundles <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod</a></li><li>Adjacent cities can swap tiles (opt-in via ModOptions unique)</li></ul>',70)])])}const p=a(l,[["render",n]]);export{m as __pageData,p as default};
